{"content":"import pytest
from roman import to_roman, from_roman


def test_subtractive_to_roman():
    assert to_roman(4) == "IV"
    assert to_roman(9) == "IX"
    assert to_roman(40) == "XL"
    assert to_roman(90) == "XC"
    assert to_roman(400) == "CD"
    assert to_roman(900) == "CM"
    assert to_roman(1994) == "MCMXCIV"


def test_to_roman_bounds():
    for invalid in [0, -1, -10, 4000, 5000, 10000, 1.5, "4"]:
        with pytest.raises(ValueError):
            to_roman(invalid)


def test_from_roman_subtractive_and_lowercase():
    assert from_roman("MCMXCIV") == 1994
    assert from_roman("xiv") == 14
    assert from_roman("XIV") == 14


def test_from_roman_rejections():
    invalid_inputs = ["", "IIII", "IC", "VX", "MMMM", "ABC", "il", "vx"]
    for invalid in invalid_inputs:
        with pytest.raises(ValueError):
            from_roman(invalid)


def test_roundtrip_all():
    for n in range(1, 4000):
        assert from_roman(to_roman(n)) == n
